parameters.jsCode:
// Get the raw text from the AI's output
const item = $input.first();

// Basic validation
if (!item.json || !item.json.output || typeof item.json.output !== 'string') {
  return { json: { error: "Input is missing or not a string" } };
}
let rawTextFromAI = item.json.output;

// --- Step 1: Un-escape Newlines ---
let processedText = rawTextFromAI.replace(/\\n/g, '\n');

// --- Step 2: Isolate the Core Markdown Content ---
const firstHeadingIndex = processedText.search(/^#+\s/m);
if (firstHeadingIndex !== -1) {
  processedText = processedText.substring(firstHeadingIndex);
} else {
  const separatorIndex = processedText.indexOf('***');
  if (separatorIndex !== -1) {
    processedText = processedText.substring(separatorIndex + 3).trim();
  }
}

// --- Step 3: Normalize Paragraph Breaks for Perfect Markdown ---
processedText = processedText.replace(/\n{3,}/g, '\n\n');

// --- Step 4: Final Polishing ---
processedText = processedText.replace(/[ \t]+\n/g, '\n');
processedText = processedText.trim();

// --- CRITICAL ADDITION: Prepare for Binary Output ---
// Derive a filename from the article's first line (the title)
const firstLineOfContent = processedText.split('\n')[0];
// Clean up Markdown heading syntax and remove invalid filename characters
const fileNameBase = firstLineOfContent.replace(/^(#+\s*)/, '').trim().substring(0, 100).replace(/[\\/:*?"<>|]/g, ''); // Max 100 chars
const fullFileName = `${fileNameBase || 'Untitled Article'}.md`; // Fallback name if title is empty

// Return the item with the content as a binary property
return [{
  json: {
    // Optionally keep the text in JSON for debugging or if other nodes need it as a string
    cleaned_post_text_string: processedText
  },
  // This 'binary' object is what the Google Drive node expects
  binary: {
    // 'markdownFile' is a key name you choose for this binary property.
    // It's what you will put in 'Input Data Field Name' in the Google Drive node.
    markdownFile: {
      data: Buffer.from(processedText, 'utf8'), // Convert the string to a Node.js Buffer
      fileName: fullFileName,
      mimeType: 'text/markdown' // Specify the MIME type
    }
  }
}];

parameters.jsonOutput:
={{
  (() => {
    // Get the raw string from the previous agent's 'output' field.
    const rawText = $json.output;

    // A defensive check to ensure we have a string to work with.
    if (!rawText || typeof rawText !== 'string') {
      throw new Error("Input from the agent was not a valid string.");
    }

    // Find the start of the JSON object (the first '{').
    const startIndex = rawText.indexOf('{');

    // Find the end of the JSON object (the last '}').
    const endIndex = rawText.lastIndexOf('}');

    // If we can't find a JSON object, throw a clear error.
    if (startIndex === -1 || endIndex === -1) {
      throw new Error("Could not find a valid JSON object within the agent's output string.");
    }

    // Extract the clean JSON string from between the start and end markers.
    const jsonString = rawText.substring(startIndex, endIndex + 1);

    // CRITICAL CHANGE: We now must explicitly 'return' the final value.
    return JSON.parse(jsonString);
  })()
}}

