const item = $input.first();

// 1. 获取原始输出
let rawOutput = item.json.output;

// 2. 核心修复：解析 JSON
// 现在的输入是被 ```json ... ``` 包裹的字符串，必须先提取并解析
let articleContent = "";

try {
    // 去除开头和结尾的 Markdown 代码块标记 (```json 和 ```)
    let cleanJsonString = rawOutput.replace(/^```json\s*/i, '').replace(/\s*```$/, '');

    // 解析 JSON
    const parsedObj = JSON.parse(cleanJsonString);

    // 提取正文内容 (字段名是 article_content)
    if (parsedObj && parsedObj.article_content) {
        articleContent = parsedObj.article_content;
    } else {
        // 如果解析成功但没找到字段，就把解析后的整个对象转字符串（兜底）
        articleContent = cleanJsonString; 
    }
} catch (e) {
    // 如果 AI 偶尔发疯没输出 JSON，而是直接输出了文章，这里做容错处理
    console.log("JSON Parse Failed, using raw text");
    articleContent = rawOutput;
}

// --- 以下是原本的清洗逻辑，现在针对的是纯净的 articleContent ---

// 3. 处理换行符 (JSON.parse 会自动处理大部分转义，这里做二次保险)
// 只有当解析失败走 catch 流程时，这一步才真正关键
let processedText = articleContent;

// 4. 去除可能残留的开篇标题前的多余内容
const firstHeadingIndex = processedText.search(/^#+\s/m);
if (firstHeadingIndex !== -1) {
  processedText = processedText.substring(firstHeadingIndex);
}

// 5. 规范化段落间距 (将3个以上换行变成2个)
processedText = processedText.replace(/\n{3,}/g, '\n\n');

// 6. 最终修整
processedText = processedText.trim();

// --- 准备文件名 ---
// 获取第一行作为文件名
const firstLineOfContent = processedText.split('\n')[0] || "Untitled";
// 清理文件名非法字符
const fileNameBase = firstLineOfContent.replace(/^(#+\s*)/, '').trim().substring(0, 100).replace(/[\\/:*?"<>|]/g, '');
const fullFileName = `${fileNameBase || 'Untitled Article'}.md`;

// --- 输出结果 ---
return [{
  json: {
    // 这里输出纯净的文本供后续节点预览
    cleaned_post_text_string: processedText
  },
  binary: {
    markdownFile: {
      data: Buffer.from(processedText, 'utf8'),
      fileName: fullFileName,
      mimeType: 'text/markdown'
    }
  }
}];
